=Извлеки название вакансии и требуемые навыки абсолютно для каждой вакансии.
Название вакансии: {{$json.items.map(item => item.name)}}
Требования: {{$json.items.map(item => item.snippet.requirement)}}

parameters.jsCode:
const text = ($json.output || "").trim();

function normalizeSkill(s) {
  s = (s || "").toLowerCase().trim();
  s = s.replace(/\s+/g, " ");

  const map = {
    "питон": "python",
    "python3": "python",
    "пандас": "pandas",
    "нумпай": "numpy",
    "машинное обучение": "machine learning",
    "мл": "machine learning",
    "дата сайнс": "data science",
    "дата-сайенс": "data science",
    "дата саенс": "data science",
    "дата сайенс": "data science",
    "дата сайенс (ds)": "data science",
    "ии": "ai",
    "искусственный интеллект": "ai",
  };

  return map[s] || s;
}

const vacancies = text.split(/\n\s*\n/).filter(v => v.trim().length > 0);
const vacanciesCount = vacancies.length;

const counts = {};

for (const block of vacancies) {
  const lines = block
    .split("\n")
    .map(s => s.trim())
    .filter(Boolean);

  for (let line of lines) {
    if (line.endsWith(":")) continue;

    line = normalizeSkill(line);
    if (!line) continue;

    counts[line] = (counts[line] || 0) + 1;
  }
}


const topSkills = Object.entries(counts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 15)
  .map(([skill, count]) => ({ skill, count }));

return [
  {
    json: {
      vacanciesCount,
      topSkills,
    },
  },
];
